import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"设计哲学","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/philosophy.md","filePath":"appendix/philosophy.md","lastUpdated":1794052435000}`),a={name:`appendix/philosophy.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="设计哲学" tabindex="-1">设计哲学 <a class="header-anchor" href="#设计哲学" aria-label="Permalink to “设计哲学”">​</a></h1><p>这一页讲 XiHan Framework 5 背后的想法：我为什么把框架分成三层承诺，七条原则怎样推出具体的设计决策，从操作系统、语言、云原生项目和诸子百家里借了什么、又把它们落成了什么规则。读完它，你会理解后面每一章里「为什么这样设计」的答案。只想学怎么用的读者可以跳过，直接去<a href="/getting-started/concepts">核心概念</a>。</p><h2 id="一页结论" tabindex="-1">一页结论 <a class="header-anchor" href="#一页结论" aria-label="Permalink to “一页结论”">​</a></h2><ol><li>十年不淘汰的不是代码，是边界。只冻结极小的一层，其余全部可替换。</li><li>框架的本体是一份语言中立的规范，加一个 .NET 参考实现。没有规范和一致性测试，多语言只是口号。</li><li>扩展有三条轴（能力包、插件、协议），共享一份清单模型和一条执行管道。</li><li>所有借鉴都要落成机器能检查的规则：分析器、API 兼容性门禁、架构测试、一致性套件。不落成隐喻，不落成类名。</li><li>默认实现必须能用。任何抽象都配一个零外部依赖、有容量上限的默认实现；五分钟起一个应用不需要任何数据库或中间件。</li><li>一个领域一个词，全链路同词。包名、命名空间、能力 ID、配置节、错误码域、文档目录共用一张术语表。</li></ol><h2 id="三易模型" tabindex="-1">三易模型 <a class="header-anchor" href="#三易模型" aria-label="Permalink to “三易模型”">​</a></h2><p>《易》有「不易、简易、变易」。这是整个方案里唯一允许进入架构骨架的哲学表达，因为它可以直接落成三层承诺：</p><table tabindex="0"><thead><tr><th>层</th><th>名称</th><th>内容</th><th>承诺</th><th>变更策略</th></tr></thead><tbody><tr><td>不易</td><td>原语层 <code>Primitives</code>（Ring 0）</td><td><code>Result&lt;T&gt;</code>、<code>Error</code>、<code>Maybe&lt;T&gt;</code>、<code>TypedId&lt;T&gt;</code>、调用上下文契约、错误码格式、清单模型、管道阶段、稳定性标记</td><td>永不破坏；跨语言语义一致</td><td>只增不改；若必须破坏，新包名并存，旧包永不删除</td></tr><tr><td>简易</td><td>内核 <code>Kernel</code>（Ring 1）</td><td>特性契约、能力图谱、执行管道、宿主、诊断抽象、安全原语、操作契约、插件宿主抽象</td><td>大版本内不破坏；大版本间提供迁移工具</td><td>三阶段弃用；每个大版本对齐一个 .NET LTS</td></tr><tr><td>变易</td><td>子系统、Provider、宿主、协议、插件、应用（Ring 2 到 6）</td><td>持久化、缓存、消息、安全、多租户、调度等抽象与实现</td><td>各自演进；通过一致性测试即视为兼容</td><td>自由演进，实验包进孵化区</td></tr></tbody></table><h2 id="七条原则" tabindex="-1">七条原则 <a class="header-anchor" href="#七条原则" aria-label="Permalink to “七条原则”">​</a></h2><table tabindex="0"><thead><tr><th>原则</th><th>含义</th><th>落在代码里的规则</th></tr></thead><tbody><tr><td>内核克制</td><td>内核只定义稳定边界，不堆能力</td><td>依赖宿主、扫描、应用工厂的东西都不进内核；内核公开类型有预算；第三方依赖为零</td></tr><tr><td>装配显式</td><td>显式注册优先，自动发现只是增强</td><td>服务在特性的 <code>Configure</code> 里显式注册，源生成器产出的登记代码也要显式调用；不扫描程序集</td></tr><tr><td>模块化不是信仰</td><td>能力包是组织方式之一，不强迫</td><td>任何实现 <code>IFeature</code> 的类都可以是一个能力包，没有基类、没有生命周期钩子</td></tr><tr><td>边界刚、内部柔</td><td>依赖方向与分层刚性约束，实现内部自由</td><td>架构测试执行依赖方向、包 ID 文法、同环只经抽象包往来；包内可以随时重构</td></tr><tr><td>宿主落地</td><td>内核不感知宿主形态</td><td>管道不绑定 HTTP；Web、命令行、消息消费、作业、插件回调走同一条管道</td></tr><tr><td>规范先于实现</td><td>公共契约先进规范，再写代码</td><td>没有 RFC 的公开 API 变更不合并；规范没有的语义不进原语层与内核</td></tr><tr><td>默认实现必须可用</td><td>每个抽象配一个默认实现</td><td>零外部设施、容量有界、可降级、通过一致性测试，只在没有显式 Provider 时生效</td></tr></tbody></table><h2 id="借鉴矩阵" tabindex="-1">借鉴矩阵 <a class="header-anchor" href="#借鉴矩阵" aria-label="Permalink to “借鉴矩阵”">​</a></h2><p>规则是：每一项借鉴都写成「借什么、落到哪、怎么检查」。写不出第三列的，只能进文档，不能进代码。下面是其中有代表性的几行。</p><h3 id="操作系统" tabindex="-1">操作系统 <a class="header-anchor" href="#操作系统" aria-label="Permalink to “操作系统”">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>借什么</th><th>落到哪</th></tr></thead><tbody><tr><td>Linux</td><td>「不破坏用户态」的系统调用 ABI</td><td>原语层只增不改，CI 包验证做基线比对</td></tr><tr><td>Linux</td><td>VFS：统一接口、可插拔文件系统</td><td>每个子系统是抽象加多个 Provider，调用方只见抽象</td></tr><tr><td>Linux</td><td><code>modprobe</code> 与符号版本</td><td>清单按能力 ID 与版本范围解析，启动期校验，缺失或冲突直接失败</td></tr><tr><td>Linux</td><td>netfilter 钩子点</td><td>执行管道定义固定阶段，特性按阶段插入中间件，不需要知道其他中间件</td></tr><tr><td>Windows NT</td><td>COM：接口一经发布不改，新能力用新接口</td><td>契约演进只加新版本并存；Provider 接口单独编号</td></tr><tr><td>Windows NT</td><td>WDK 与 HLK 认证</td><td>Provider 开发套件与一致性测试套件；通过套件才能标 Stable</td></tr><tr><td>macOS</td><td>XNU 混合内核：微内核原语加开箱即用的 BSD 层</td><td>微内核抽象加默认实现，不让使用者面对一堆空接口</td></tr><tr><td>macOS</td><td>launchd 按依赖启动</td><td>特性生命周期状态机</td></tr><tr><td>Android</td><td>Project Treble：供应商接口独立版本化</td><td>Provider 接口单独版本化，写好的 Provider 在同一大版本内全程可用</td></tr><tr><td>Android</td><td>清单声明权限、运行时授予</td><td>插件权限模型</td></tr><tr><td>鸿蒙</td><td>系统能力注册与发现，本地远程透明</td><td>同一能力可由同进程、插件或远程协议提供</td></tr></tbody></table><h3 id="语言与框架" tabindex="-1">语言与框架 <a class="header-anchor" href="#语言与框架" aria-label="Permalink to “语言与框架”">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>借什么</th><th>落到哪</th></tr></thead><tbody><tr><td>.NET</td><td>Generic Host、Options、源生成器、AOT、<code>TimeProvider</code>、<code>System.Threading.RateLimiting</code>、<code>Microsoft.Extensions.AI</code></td><td>只扩展不包装；内核依赖仅限 <code>Microsoft.Extensions.*</code> 抽象包</td></tr><tr><td>Spring</td><td>条件装配</td><td>默认实现只在没有显式 Provider 时生效，且在启动日志里可见</td></tr><tr><td>Go</td><td>小接口加组合；<code>context.Context</code> 传播取消、截止、值</td><td>调用上下文必带取消、截止、Trace、Baggage</td></tr><tr><td>Rust</td><td><code>core</code> 与 <code>std</code> 分层；默认私有、显式公开；<code>Result</code> 与 <code>Option</code></td><td>原语层不依赖宿主；默认 <code>internal</code>，公开面受 PublicAPI 文件约束</td></tr><tr><td>FastAPI</td><td>类型即契约，自动校验与 OpenAPI</td><td>操作契约由类型生成 Schema，源生成器产出 OpenAPI、proto 与 MCP tool</td></tr><tr><td>ASGI</td><td>服务器与应用之间的协议</td><td>XGI：协议适配器与管道之间的消息契约</td></tr><tr><td>Vue</td><td>渐进式，用多少装多少</td><td>从 Minimal 一路加到 Full</td></tr><tr><td>React</td><td>单向数据流；Error Boundary</td><td>管道单向；插件失败隔离在边界内，宿主不崩</td></tr><tr><td>ABP</td><td>模块化单体的完整度</td><td>作为子系统能力清单的对照表，不继承其强制基类与钩子</td></tr></tbody></table><h3 id="云原生与开源项目" tabindex="-1">云原生与开源项目 <a class="header-anchor" href="#云原生与开源项目" aria-label="Permalink to “云原生与开源项目”">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>借什么</th><th>落到哪</th></tr></thead><tbody><tr><td>Kubernetes</td><td>探针、SIGTERM 与宽限期、ConfigMap 热更新、API 版本演进</td><td>探针直接映射特性状态机；Draining 状态；配置目录监听；能力契约版本规则</td></tr><tr><td>Service Binding</td><td>工作负载声明需要的资源，平台注入</td><td>清单 <code>bindings</code></td></tr><tr><td>OpenTelemetry 与 MCP</td><td>规范加多语言 SDK 加一致性测试</td><td>XiHan Spec 的组织方式</td></tr><tr><td>Dapr</td><td>Building Blocks；可插拔组件走 gRPC</td><td>子系统端口集合；远程 Provider</td></tr><tr><td>Terraform</td><td>子进程加 gRPC 的跨语言插件</td><td>进程外插件协议</td></tr><tr><td>VS Code</td><td>贡献点、激活事件、扩展宿主进程隔离</td><td>插件清单的 <code>contributes</code> 与 <code>activation</code>；进程外插件宿主</td></tr><tr><td>Envoy</td><td>过滤器链、Wasm 过滤器</td><td>管道阶段；Wasm 插件可贡献中间件</td></tr><tr><td>Roslyn</td><td>PublicAPI 分析器、源生成器</td><td>公开面文件化；生成器替代反射</td></tr></tbody></table><h3 id="诸子百家" tabindex="-1">诸子百家 <a class="header-anchor" href="#诸子百家" aria-label="Permalink to “诸子百家”">​</a></h3><p>硬性规则：思想只能变成约束，不能变成类名或 API。代码里不出现 <code>Dao</code>、<code>Wuwei</code> 这类标识符。</p><table tabindex="0"><thead><tr><th>思想</th><th>工程约束</th><th>机器检查</th></tr></thead><tbody><tr><td>《易》不易、简易、变易</td><td>三层承诺</td><td>包验证基线按层分级</td></tr><tr><td>道家 无为、大道至简</td><td>内核不自动注册、不扫描、不推断；默认实现零配置可用</td><td>内核公开类型预算、零反射分析器</td></tr><tr><td>道家 反者道之动</td><td>任何能力都可被移除，应用仍可编译</td><td>移除能力后的编译测试</td></tr><tr><td>道家 上善若水</td><td>内核不感知宿主形态</td><td>架构测试：内核不引用任何宿主包</td></tr><tr><td>儒家 正名</td><td>能力 ID、错误码、Baggage 键、操作 ID 是规范化命名，一经发布不改</td><td>命名注册表、分析器、包 ID 文法测试</td></tr><tr><td>儒家 礼</td><td>互操作标准就是「礼」：跨语言、跨实现共同遵守</td><td>一致性测试</td></tr><tr><td>儒家 中庸</td><td>显式优先，约定可用，二者都有退出机制</td><td>约定行为必须有显式覆盖 API</td></tr><tr><td>法家 以法治</td><td>规则由工具执行，不靠人审</td><td>分析器、架构测试、API 兼容性作为 CI 必过项</td></tr><tr><td>墨家 节用</td><td>资源有界；不锁定供应商</td><td>容量测试；抽象包不暴露第三方类型</td></tr><tr><td>兵家 先胜后战</td><td>发布前过全部门禁；稳定主线加孵化区</td><td>孵化包只能标 Experimental</td></tr></tbody></table><h3 id="明确不借" tabindex="-1">明确不借 <a class="header-anchor" href="#明确不借" aria-label="Permalink to “明确不借”">​</a></h3><p>不做 Reconcile Loop 内核；不做 Sidecar；不做 OSGi 式运行时服务总线；不做低代码平台、不做 UI；不把哲学词汇写进标识符。</p><h2 id="反模式清单" tabindex="-1">反模式清单 <a class="header-anchor" href="#反模式清单" aria-label="Permalink to “反模式清单”">​</a></h2><table tabindex="0"><thead><tr><th>反模式</th><th>避免方式</th></tr></thead><tbody><tr><td>上帝基类</td><td>无基类，只实现 <code>IFeature</code></td></tr><tr><td>隐式依赖</td><td>清单按能力 ID 声明，启动期求解并可打印</td></tr><tr><td>深层继承</td><td>接口组合，零层继承</td></tr><tr><td>反射魔法</td><td>源生成器加显式注册</td></tr><tr><td>包爆炸</td><td>抽象与实现分层、共享版本线、组合包</td></tr><tr><td>隐喻命名</td><td>思想只能变成约束，标识符里不出现哲学词汇</td></tr><tr><td>策略进包名</td><td><code>Default</code> 不进包名，实现按机制或技术命名</td></tr><tr><td>没有默认实现的抽象</td><td>每个抽象必须有 <code>InMemory</code> 之类的默认实现并通过一致性测试</td></tr></tbody></table><h2 id="十年稳定性治理" tabindex="-1">十年稳定性治理 <a class="header-anchor" href="#十年稳定性治理" aria-label="Permalink to “十年稳定性治理”">​</a></h2><table tabindex="0"><thead><tr><th>门禁</th><th>工具</th><th>规则</th></tr></thead><tbody><tr><td>公开面文件化</td><td>PublicAPI 分析器</td><td>每包一份 <code>PublicAPI.Shipped.txt</code>；原语层已发布行不可改</td></tr><tr><td>包验证</td><td>.NET SDK 包验证加基线版本</td><td>小版本禁止破坏；大版本列出破坏清单</td></tr><tr><td>稳定性标记</td><td>自研分析器</td><td>公开类型必须有 <code>[ApiLevel]</code>；<code>Internal</code> 被引用即报错</td></tr><tr><td>命名文法</td><td>架构测试</td><td>包 ID、命名空间、能力 ID、配置节、错误码域符合术语表与文法</td></tr><tr><td>架构边界</td><td>架构测试</td><td>依赖方向、抽象包不含第三方类型、内核零反射、批量优先、本地化文件齐全</td></tr><tr><td>AOT</td><td>CI 发布冒烟</td><td>裁剪警告视为错误</td></tr><tr><td>一致性</td><td>Conformance 套件</td><td>Provider 标 Stable 的前提</td></tr></tbody></table><p>弃用流程：标 <code>Deprecated</code> 并以 <code>[Obsolete]</code> 给出警告与迁移文档，至少跨两个小版本；下一个大版本前的最后一个小版本升级为编译错误；大版本移除并提供代码修复。</p><h2 id="借鉴的边界" tabindex="-1">借鉴的边界 <a class="header-anchor" href="#借鉴的边界" aria-label="Permalink to “借鉴的边界”">​</a></h2><p>借鉴分三档：可落成机器检查的规则，进代码、分析器与架构测试；可落成文档约束的，进规范与审查清单；只是启发的，留在设计说明里，不进代码。写不出前两档的借鉴，一律按第三档处理。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/appendix/spec">规范与多语言</a>：规范怎样组织，一致性测试怎样保证多语言实现的一致</li><li><a href="/getting-started/concepts">核心概念</a>：这些原则在代码里长什么样</li></ul>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};